#!/usr/bin/env python3
"""Generate offline CSS data-URI wallpapers from the exact checked-in JPEGs.

Expected source files (copied from the user's original JPEG attachments):
  aurora-and-mountain.jpg       2048x1152
  octavian-marine-dual-brand.jpg 1672x941

The original JPEG bytes are preserved verbatim inside each data URI. No network
access, re-encoding, resizing, or third-party image library is required.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import re
from pathlib import Path

EXPECTED = {
    "aurora-and-mountain.jpg": {
        "id": "chimera-aurora-mountain",
        "selector": ".aurora-wallpaper--default",
        "width": 2048,
        "height": 1152,
        "background": "#07121c",
    },
    "octavian-marine-dual-brand.jpg": {
        "id": "octavian-marine-dual-brand",
        "selector": ".marine-wallpaper--default",
        "width": 1672,
        "height": 941,
        "background": "#070914",
    },
}


def jpeg_dimensions(data: bytes) -> tuple[int, int]:
    if len(data) < 4 or data[:2] != b"\\xff\\xd8" or data[-2:] != b"\\xff\\xd9":
        raise ValueError("not a complete JPEG stream (SOI/EOI markers missing)")
    i = 2
    sof = {0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF}
    while i < len(data) - 4:
        if data[i] != 0xFF:
            i += 1
            continue
        while i < len(data) and data[i] == 0xFF:
            i += 1
        if i >= len(data):
            break
        marker = data[i]
        i += 1
        if marker in (0xD8, 0xD9) or 0xD0 <= marker <= 0xD7 or marker == 0x01:
            continue
        if i + 2 > len(data):
            break
        seg_len = int.from_bytes(data[i:i + 2], "big")
        if seg_len < 2 or i + seg_len > len(data):
            raise ValueError("invalid JPEG segment length")
        if marker in sof:
            if seg_len < 8:
                raise ValueError("short JPEG frame header")
            height = int.from_bytes(data[i + 3:i + 5], "big")
            width = int.from_bytes(data[i + 5:i + 7], "big")
            if width <= 0 or height <= 0:
                raise ValueError("invalid JPEG dimensions")
            return width, height
        i += seg_len
    raise ValueError("JPEG frame dimensions were not found")


def generate(source_dir: Path, css_path: Path, manifest_path: Path) -> dict:
    css = [
        "/* Generated by tools/wallpapers/embed_wallpapers.py; do not hand-edit. */",
        "/* Images are embedded as original JPEG data URIs for offline startup. */",
        ".aurora-wallpaper--default, .marine-wallpaper--default {",
        "  display: block;",
        "  background-position: center center;",
        "  background-repeat: no-repeat;",
        "  background-size: cover;",
        "}",
        ".aurora-wallpaper--default { background-color: #07121c; }",
        ".marine-wallpaper--default { background-color: #070914; }",
        ".aurora-wallpaper--fallback, .marine-wallpaper--fallback {",
        "  background-image: none !important;",
        "  background-color: #080b12;",
        "}",
        "",
    ]
    entries = []
    for filename, spec in EXPECTED.items():
        path = source_dir / filename
        if not path.is_file():
            raise FileNotFoundError(f"required original wallpaper is missing: {path}")
        raw = path.read_bytes()
        width, height = jpeg_dimensions(raw)
        if (width, height) != (spec["width"], spec["height"]):
            raise ValueError(
                f"{filename}: expected {spec['width']}x{spec['height']}, got {width}x{height}"
            )
        encoded = base64.b64encode(raw).decode("ascii")
        if not re.fullmatch(r"[A-Za-z0-9+/]*={0,2}", encoded):
            raise ValueError(f"{filename}: Base64 encoder produced invalid output")
        css.append(
            f'{spec["selector"]} {{ background-image: url("data:image/jpeg;base64,{encoded}"); }}'
        )
        entries.append({
            "id": spec["id"],
            "file": filename,
            "mime_type": "image/jpeg",
            "width": width,
            "height": height,
            "bytes": len(raw),
            "sha256": hashlib.sha256(raw).hexdigest(),
            "data_uri_prefix": "data:image/jpeg;base64,",
            "embedded": True,
            "offline": True,
            "fit": "cover",
            "dark_fallback": spec["background"],
        })
    css_path.parent.mkdir(parents=True, exist_ok=True)
    manifest_path.parent.mkdir(parents=True, exist_ok=True)
    css_path.write_text("\n".join(css) + "\n", encoding="utf-8")
    manifest_path.write_text(json.dumps({
        "schema": "CHM-EMBEDDED-WALLPAPERS-1",
        "source": "original user-provided JPEG bytes; no re-encoding",
        "wallpapers": entries,
    }, indent=2) + "\n", encoding="utf-8")
    return {"css": str(css_path), "manifest": str(manifest_path), "wallpapers": entries}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-dir", type=Path, default=Path("desktop/aurora/assets/library"))
    parser.add_argument("--css", type=Path, default=Path("desktop/aurora/assets/embedded-wallpapers.css"))
    parser.add_argument("--manifest", type=Path, default=Path("desktop/aurora/assets/embedded-wallpapers.json"))
    args = parser.parse_args()
    result = generate(args.source_dir, args.css, args.manifest)
    print(json.dumps(result, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
